import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def transform(g):
    from collections import Counter
    c=Counter(v for row in g for v in row)
    bg=c.most_common(1)[0][0]
    # template: contiguous non-bg run that isn't the anchor color? find anchor color = the scattered one
    # find template = longest contiguous run of non-bg cells
    runs=[]
    for i,row in enumerate(g):
        j=0
        while j<len(row):
            if row[j]!=bg:
                k=j
                while k<len(row) and row[k]!=bg: k+=1
                runs.append((k-j,i,j,row[j:k])); j=k
            else: j+=1
    runs.sort(reverse=True)
    L,i0,j0,temp=runs[0]
    anchor=next(v for v in c if v!=bg and v not in set(temp))
    out=[row[:] for row in g]
    off=L//2
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v==anchor:
                for t,(jj,x) in enumerate(zip(range(j-off,j-off+L),temp)):
                    if 0<=jj<len(row): out[i][jj]=x
    return out
